import math

REUSE_THRESHOLD = 0.4
REDUNDANCY_CUTOFF = 0.6


def cosine(u, v):
    du = math.sqrt(sum(a * a for a in u))
    dv = math.sqrt(sum(b * b for b in v))
    if du == 0 or dv == 0:
        return 0.0
    return sum(a * b for a, b in zip(u, v)) / (du * dv)


def select(query, skills, k=3):
    """Pick up to k skills for one query.

    `skills` is a list of (name, vector) pairs. Returns the chosen names,
    most relevant first.
    """
    scored = sorted(
        ((cosine(query, vec), name, vec) for name, vec in skills),
        key=lambda t: -t[0],
    )
    chosen = []
    for score, name, vec in scored:
        if score < REUSE_THRESHOLD:
            continue
        if any(cosine(vec, other) > REDUNDANCY_CUTOFF for _, other in chosen):
            continue
        chosen.append((name, vec))
        if len(chosen) == k:
            break
    return [name for name, _ in chosen]

