import answer

QUERY = [1.0, 0.0, 0.0]
PARSE = ("parse-invoice", [0.8, 0.6, 0.0])
CHART = ("chart-totals", [0.8, 0.0, 0.6])
PARSE_DUP = ("parse-invoice-v2", [0.8, 0.6, 0.0])
LOOSE = ("reconcile-ledger", [0.45, 0.893, 0.0])


def test_loose_match_is_not_reused():
    assert answer.select(QUERY, [LOOSE]) == []


def test_complementary_pair_both_selected():
    got = answer.select(QUERY, [PARSE, CHART])
    assert set(got) == {"parse-invoice", "chart-totals"}


def test_redundant_duplicate_is_dropped():
    got = answer.select(QUERY, [PARSE, PARSE_DUP])
    assert len(got) == 1


def test_complementary_pair_survives_beside_a_duplicate():
    got = answer.select(QUERY, [PARSE, PARSE_DUP, CHART])
    assert set(got) == {"parse-invoice", "chart-totals"}


def test_loose_match_is_not_reused_even_when_it_is_the_best_available():
    assert answer.select(QUERY, [LOOSE, ("stale-import", [0.3, 0.95, 0.0])]) == []


def test_relevance_order_is_kept():
    strong = ("strong", [0.95, 0.31, 0.0])
    got = answer.select(QUERY, [CHART, strong])
    assert got[0] == "strong"

